SELECT account_id, ROUND(COUNT(*) FILTER (WHERE priority = 'urgent')::numeric / NULLIF(COUNT(*), 0), 4) AS urgent_ticket_share
FROM support_tickets
GROUP BY account_id;

SELECT ticket_id, status
FROM support_tickets
WHERE payload ->> 'channel' = 'chat';

SELECT subscription_id
FROM subscriptions
WHERE status = 'active';

SELECT da.invoice_id, MAX(da.attempted_at) AS latest_dunning_attempt_at
FROM dunning_attempts AS da
GROUP BY da.invoice_id;

SELECT customer_id, risk_score
FROM (
    SELECT customer_id, risk_score,
           ROW_NUMBER() OVER (
               PARTITION BY customer_id
               ORDER BY assessed_at DESC, assessment_id DESC
           ) AS rn
    FROM risk_assessments
) AS ranked
WHERE rn = 1;

SELECT transaction_id
FROM transactions
WHERE (payload #>> '{risk_score}')::numeric >= 80;

SELECT s.subscription_id, a.account_name
FROM subscriptions AS s
JOIN accounts AS a ON a.account_id = s.account_id;
